// Assemble the OpenRouter payload. The Merge node passes through either
// the weather result (location granted) or the webhook data (no location).
const hook = $('Webhook (analyze)').first().json;
const source = $('Merge').first().json;

const hasWeather =
  source && source.main && (source.main.temp !== undefined || source.main.humidity !== undefined);
const temp = hasWeather ? source.main.temp : 'N/A';
const humidity = hasWeather ? source.main.humidity : 'N/A';

const prompt = `You are the PhytoScan AI, a world-class botanist. Analyze the provided image and the environmental data (Temp: ${temp}°C, Humidity: ${humidity}%).

Respond with ONE JSON object, in exactly this schema, following the types EXACTLY:
{
  "identification": {
    "name": "string (common plant name)",
    "scientific_name": "string (binomial name)",
    "confidence": "string stating a percentage, e.g. \"87%\" (must end with the % sign)"
  },
  "health_assessment": {
    "status": "exactly one of: Healthy, Warning, Critical",
    "diagnosis": "string",
    "needs_water": "boolean (true or false)",
    "needs_medicine": "boolean (true or false)"
  },
  "light_analysis": {
    "current_light": "string",
    "recommendation": "string"
  },
  "care_instructions": {
    "watering_frequency": "string",
    "soil_type": "string",
    "toxicity": "exactly one of: Safe, Toxic for pets"
  },
  "environmental_impact": "string — how the current local weather (${temp}/${humidity}) affects this specific plant.",
  "fun_fact": "string"
}

HARD RULES:
- Return ONLY a valid JSON object — no markdown, no code fences, no preface, no trailing text.
- confidence MUST be a string ending with "%".
- status MUST be exactly one of Healthy / Warning / Critical.
- toxicity MUST be exactly one of Safe / Toxic for pets.
- needs_water and needs_medicine MUST be JSON booleans (true/false), never strings.
- Do not use ellipses or placeholders — always fill real text values.
- If there are spots or lesions on leaves, name the specific fungus, pest, or deficiency in "diagnosis".`;

const encoded = $('Encode image').first().json;
const imagePart = encoded && encoded.imageUrl
  ? [{ type: 'image_url', image_url: { url: encoded.imageUrl } }]
  : [];

return [{
  json: {
    messages: [{
      role: 'user',
      content: [{ type: 'text', text: prompt }, ...imagePart]
    }],
    scanId: hook.scanId || '',
    imageUrl: hook.imageUrl || '',
    temp: temp,
    humidity: humidity,
    lat: hook.lat || null,
    lng: hook.lng || null
  }
}];

const raw = $input.all()[0].json;
const msg = raw.choices?.[0]?.message ?? {};
const content = Array.isArray(msg.content)
  ? msg.content.map((part) => part.text ?? part.content ?? '').join('')
  : (msg.content || msg.reasoning || '');

if (!String(content).trim()) {
  throw new Error('No content from OpenRouter. Raw: ' + JSON.stringify(raw).slice(0, 400));
}

const cleaned = String(content).replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
let analysis;
try {
  analysis = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI response was not valid JSON: ' + cleaned.slice(0, 200));
}

const ctx = $('Build context').first().json;

return [{
  json: {
    analysis: analysis,
    imageUrl: ctx.imageUrl || '',
    temp: ctx.temp,
    humidity: ctx.humidity,
    lat: ctx.lat,
    lng: ctx.lng,
    created_at: new Date().toISOString()
  }
}];

const resolved = $('Resolve image').first().json;
if (resolved.dataUrl) return [{ json: { imageUrl: resolved.dataUrl } }];

const item = $input.all()[0];
if (item && item.binary && item.binary.data) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buffer && buffer.length > 0) {
    const mime = item.binary.data.mimeType || 'image/jpeg';
    return [{ json: { imageUrl: 'data:' + mime + ';base64,' + buffer.toString('base64') } }];
  }
}

const hook = $('Webhook (analyze)').first().json;
throw new Error('No image received. Webhook keys: ' + Object.keys(hook).join(', ') + ' | imageUrl: ' + (hook.imageUrl || '(none)') + ' | base64Image: ' + (hook.base64Image ? '(present, length ' + String(hook.base64Image).length + ')' : '(none)'));

const hook = $('Webhook (analyze)').first().json;
const raw =
  typeof hook.imageUrl === 'string' && hook.imageUrl.trim() !== '' ? hook.imageUrl
  : (typeof hook.base64Image === 'string' && hook.base64Image.trim() !== '' ? hook.base64Image
  : '');
const dataUrl = raw.startsWith('data:') ? raw : '';
return [{ json: { ...hook, url: dataUrl ? '' : raw, dataUrl } }];
